shablon_all = [shablon1, shablon2]

class VSpamMod(loader.Module):
	"""Vspam"""
	strings = {'name': 'VSpamMod'}
	async def client_ready(self, client, db):
		self.db = db

	async def vampcmd(self, message):
		""".vamp {time} {id/user chat} {text} """
		args = utils.get_args_raw(message)
		reply = await message.get_reply_message()
		file = None
		if reply and reply.file: file = reply
		if not args:
			return await utils.answer(message, '<b>Где аргументы?</b>')
		args = args.split(' ', maxsplit=2)
		try:
			time = float(args[0])
		except:
			return await utils.answer(message, '<b>Время указывать цифрами!</b>')
		if args[1].isdigit():
			args[1] = int(args[1])
		try: 
			args[2] = args[2]
		except:
			args.append('')
		status = self.db.set("VSpamMod", "status", True)
		await message.delete()
		while status:
			try:
				await message.client.send_message(args[1], args[2]+" "+choice(shablon_all[self.db.get('VSpamMod', 'shablon', 1) - 1]), file=file)
				await sleep(time)
			except Exception as e:
				return await message.respond(f"Ошибка:\n" + str(e))
			if not self.db.get("VSpamMod", "status"): return

	async def voffcmd(self, message):
		""" stop spam. """
		self.db.set('VSpamMod', 'status', False)
		await utils.answer(message, '<b>Остановлено</b>')

	async def vampidcmd(self, message):
		""" send mes to favourites"""
		reply = await message.get_reply_message()
		me = await message.client.get_me()
		if not reply:
			i = str(message.chat_id)
		else:
			i = str(reply.sender_id)
		if i.startswith('-100'):
			i = i[4:]
		await message.client.send_message(me.id, f"<code>{i}</code>")
		await message.delete()

	async def vchcmd(self, message):
		""" Выбор шаблона """
		args = utils.get_args_raw(message)
		if not args:
			return await utils.answer(message, '<b>Выберите шаблон:</b>\n1 --- много шаблонов в одном.\n2 --- шаблон вампа.')
		if args.isdigit() and int(args) >= 1 and int(args) <= len(shablon_all):
			self.db.set('VSpamMod', 'shablon', int(args))
		else:
			 await utils.answer(message, '<b>Вводите только цифры.</b>')